function Stop-RminsTargetProcesses {
    param(
        [Parameter(Mandatory)]
        [string]$TargetPath
    )

    $prefix = (Test-RminsTarget -Path $TargetPath).TrimEnd('\') + '\'
    $protected = Get-RminsCurrentProcessIds
    $matched = @(
        Get-CimInstance Win32_Process -ErrorAction Stop |
            Where-Object {
                $executable = '' + $_.ExecutablePath
