                ($executable.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase) -or
                    $commandLine.IndexOf($prefix, [StringComparison]::OrdinalIgnoreCase) -ge 0)
            }
    )

    foreach ($process in $matched) {
        $label = '{0}[{1}]' -f $process.Name, $process.ProcessId
