            try {
                Stop-Process -Id $process.ProcessId -Force -ErrorAction Stop
                Write-Host ("RMINS_PROCESS_STOPPED process={0}" -f $label) -ForegroundColor Green
            }
            catch {
                throw ("rmins: could not stop {0}: {1}" -f $label, $_.Exception.Message)
            }
